<script setup lang="ts">import{onMounted,ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import{api}from'../../api/client';import type{DirectoryItem}from'../../domain/types';const items=ref<DirectoryItem[]>([]),loading=ref(true),error=ref('');onMounted(async()=>{try{items.value=(await api.getDirectory()).filter(i=>i.publicationState==='ELIGIBLE')}catch{error.value='内容读取失败'}finally{loading.value=false}});function open(i:DirectoryItem){uni.setStorageSync('directoryItem',i);uni.navigateTo({url:'/pages/directory/detail'})}</script>
<template><view class="page"><AppHeader left="首页" right="报错" @left="uni.reLaunch({url:'/pages/index/index'})"/><view class="content"><text class="kicker">信息与黄页 / UX-P040</text><view class="heading" role="heading" aria-level="1">在孟实用信息</view><text class="desc">仅展示公司自营且当前具备发布资格的静态信息，不做付费排名、推荐或担保。</text><view v-if="loading" class="card" role="status">加载中…</view><view v-if="error" class="card" role="alert">{{error}}</view><button v-for="item in items" :key="item.contentRef" class="card item" :aria-label="`查看信息 ${item.title}`" @click="open(item)"><view class="avatar">孟</view><view><text class="card-title">{{item.title}}</text><text class="verified">✓ 指定范围已核验</text><text class="copy">{{item.sourceType}} · 更新 {{item.updatedAt}}</text></view></button><view v-if="!loading&&!error&&!items.length" class="card">暂无具备发布资格的信息；空状态与读取失败分开。</view></view></view></template><style src="../../styles/shared.css"></style><style scoped>.item{width:100%;display:flex;gap:22rpx;text-align:left;line-height:1.4}.avatar{width:80rpx;height:80rpx;border-radius:22rpx;background:#fff3e8;color:#9a531d;font-weight:900;display:flex;align-items:center;justify-content:center;flex:none}.verified{display:block;font-size:21rpx;color:var(--success);margin-top:10rpx}</style>
